import React, { useState } from "react";
import { Plus } from "lucide-react";
import JobStats from "../components/JobStats";
import JobForm from "../components/JobForm";
import JobTable from "../components/JobTable";

function JobAdminPage() {
  const [jobs, setJobs] = useState([]);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingJob, setEditingJob] = useState(null);

  const addOrUpdateJob = (job) => {
    if (editingJob) {
      setJobs(
        jobs.map((j) =>
          j.id === editingJob.id
            ? { ...job, id: editingJob.id, createdAt: j.createdAt }
            : j
        )
      );
      setEditingJob(null);
    } else {
      setJobs([
        ...jobs,
        { ...job, id: Date.now(), createdAt: new Date().toLocaleDateString() },
      ]);
    }
    setIsFormOpen(false);
  };

  const handleEdit = (job) => {
    setEditingJob(job);
    setIsFormOpen(true);
  };

  const handleDelete = (id) => {
    if (confirm("Are you sure you want to delete this job posting?")) {
      setJobs(jobs.filter((job) => job.id !== id));
    }
  };

  const styles = {
    page: {
      minHeight: "100vh",
      backgroundColor: "#F9FAFB",
      padding: "24px",
    },
    container: {
      maxWidth: "1200px",
      margin: "0 auto",
    },
    header: {
      backgroundColor: "#fff",
      borderRadius: "8px",
      boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
      padding: "24px",
      marginBottom: "24px",
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
    },
    title: {
      fontSize: "1.875rem",
      fontWeight: "700",
      color: "#111827",
      margin: 0,
    },
    addButton: {
      display: "flex",
      alignItems: "center",
      gap: "8px",
      backgroundColor: "#2563EB", // blue-600
      color: "#fff",
      padding: "8px 16px",
      borderRadius: "8px",
      border: "none",
      cursor: "pointer",
      fontSize: "1rem",
    },
    addButtonHover: {
      backgroundColor: "#1D4ED8", // blue-700
    },
  };

  return (
    <div style={styles.page}>
      <div style={styles.container}>
        {/* Header */}
        <div style={styles.header}>
          <h1 style={styles.title}>Job Administration</h1>
          <button
            onClick={() => setIsFormOpen(true)}
            style={styles.addButton}
          >
            <Plus size={20} /> Add New Job
          </button>
        </div>

        {/* Stats */}
        <JobStats jobs={jobs} />

        {/* Jobs Table */}
        <JobTable jobs={jobs} onEdit={handleEdit} onDelete={handleDelete} />

        {/* Job Form Modal */}
        {isFormOpen && (
          <JobForm
            job={editingJob}
            onClose={() => setIsFormOpen(false)}
            onSubmit={addOrUpdateJob}
          />
        )}
      </div>
    </div>
  );
}

export default JobAdminPage;
